// and found says whether there is any value.
func (q *Queries) UsageDistinctMonths(ctx context.Context, arg UsageDistinctMonthsParams) ([]UsageDistinctMonthsRow, error) {
	rows, err := q.db.Query(ctx, usageDistinctMonths,
		arg.Customers,
		arg.MeterCodes,
		arg.FromIds,
		arg.ToIds,
		arg.Generation,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UsageDistinctMonthsRow{}
	for rows.Next() {
		var i UsageDistinctMonthsRow
		if err := rows.Scan(&i.DistinctValues, &i.Found); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

